module.exports = async function(data) {
  const RESEND_API_KEY   = env['RESEND_API_KEY'];
  const RESEND_FROM      = env['RESEND_FROM'] || 'Centavo <hola@centavos.mx>';
  const SITE_URL         = env['CENTAVOS_SITE_URL'] || 'https://centavos.mx';

  const articles    = data.read_articles    || [];
  const subscribers = data.read_subscribers || [];

  if (!RESEND_API_KEY) throw new Error('RESEND_API_KEY not set in Directus environment');
  if (articles.length === 0) return { ok: false, reason: 'No published articles found' };
  if (subscribers.length === 0) return { ok: true, sent: 0, reason: 'No confirmed subscribers' };

  // ── Brand tokens ──────────────────────────────────────────
  const BG        = '#faf3e3';
  const SURFACE   = '#ffffff';
  const MANDARINA = '#ed7e3c';
  const INK       = '#2a1a10';
  const INK_SOFT  = '#6e5849';
  const RULE      = '#ead9c2';
  const SAND      = '#f5ead0';
  const FONT      = "-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif";

  const CATEGORY_LABELS = {
    ahorro: 'Ahorro', deuda: 'Deuda', inversion: 'Inversión',
    credito: 'Crédito', impuestos: 'Impuestos', basicos: 'Básicos',
  };

  // ── Edition label (e.g. "Mayo 2026") ────────────────────
  const edition = new Intl.DateTimeFormat('es-MX', {
    month: 'long', year: 'numeric', timeZone: 'America/Los_Angeles',
  }).format(new Date());

  const subject = `Centavo · Lo de esta semana (${edition})`;

  // ── Article card HTML ────────────────────────────────────
  function articleCard(a) {
    const url = `${SITE_URL}/articulos/${a.slug}`;
    const cat = CATEGORY_LABELS[a.category] || a.category;
    const mins = a.read_minutes || 0;
    return `
      <tr><td style="padding:0 0 14px;">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
               style="background:${SAND};border-radius:16px;overflow:hidden;">
          <tr><td style="padding:18px 22px;">
            <div style="font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:${MANDARINA};margin-bottom:5px;">
              ${cat} &middot; ${mins} min
            </div>
            <h2 style="font-size:16px;font-weight:800;line-height:1.2;margin:0 0 7px;color:${INK};">
              <a href="${url}" style="color:${INK};text-decoration:none;">${a.title}</a>
            </h2>
            <p style="font-size:13px;line-height:1.6;color:${INK_SOFT};margin:0 0 12px;">${a.excerpt}</p>
            <a href="${url}" style="font-size:13px;font-weight:700;color:${MANDARINA};text-decoration:none;">Leer art&iacute;culo &rarr;</a>
          </td></tr>
        </table>
      </td></tr>`;
  }

  // ── Full email HTML (personalized per subscriber) ────────
  function buildHtml(preferencesUrl) {
    const cards = articles.map(articleCard).join('');
    return `<!doctype html>
<html lang="es">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width,initial-scale=1"/>
<title>${subject}</title>
</head>
<body style="margin:0;padding:0;background:${BG};font-family:${FONT};color:${INK};">
  <div style="display:none;max-height:0;overflow:hidden;font-size:1px;color:${BG};">
    Los 5 art&iacute;culos de esta semana, sin jerga ni paja. &nbsp;&zwnj;&nbsp;&zwnj;
  </div>
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="background:${BG};">
    <tr><td align="center" style="padding:32px 16px;">
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"
             style="max-width:560px;background:${SURFACE};border-radius:24px;overflow:hidden;">
        <tr><td style="background:${MANDARINA};padding:30px 30px 26px;">
          <div style="font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:${INK};opacity:.7;margin-bottom:7px;">${edition}</div>
          <h1 style="font-size:26px;line-height:1.08;font-weight:800;letter-spacing:-0.02em;margin:0;color:${INK};">
            Lo de esta semana<br/>en Centavo 📬
          </h1>
          <p style="font-size:14px;line-height:1.5;color:${INK};opacity:.8;margin:9px 0 0;">Cinco art&iacute;culos de dinero, sin jerga ni paja.</p>
        </td></tr>
        <tr><td style="padding:24px 22px 8px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
            ${cards}
          </table>
        </td></tr>
        <tr><td align="center" style="padding:4px 30px 26px;">
          <a href="${SITE_URL}"
             style="display:inline-block;background:${INK};color:${BG};text-decoration:none;font-weight:700;font-size:14px;padding:13px 26px;border-radius:14px;">
            Ver todos los art&iacute;culos
          </a>
        </td></tr>
        <tr><td style="padding:0 30px;"><div style="height:1px;background:${RULE};font-size:1px;">&nbsp;</div></td></tr>
        <tr><td style="padding:18px 30px 26px;">
          <p style="font-size:12px;line-height:1.55;color:${INK_SOFT};margin:0 0 7px;">
            Recibes este correo porque te suscribiste en centavos.mx.
            Este bolet&iacute;n llega cada martes a las 8 AM (hora del Pac&iacute;fico).
          </p>
          <p style="font-size:12px;line-height:1.55;color:${INK_SOFT};margin:0;">
            <a href="${preferencesUrl}" style="color:${INK_SOFT};text-decoration:underline;">Preferencias</a>
            &nbsp;&middot;&nbsp;
            <a href="${preferencesUrl}" style="color:${INK_SOFT};text-decoration:underline;">Darme de baja</a>
            &nbsp;&middot;&nbsp;
            <a href="${preferencesUrl}" style="color:${INK_SOFT};text-decoration:underline;">Manejar preferencias</a>
          </p>
        </td></tr>
      </table>
      <div style="font-size:11px;color:${INK_SOFT};margin-top:14px;opacity:.6;">&copy; Centavo &middot; MX</div>
    </td></tr>
  </table>
</body>
</html>`;
  }

  // ── Send one email per subscriber ────────────────────────
  let sent = 0;
  const failed = [];

  for (const sub of subscribers) {
    const preferencesUrl = `${SITE_URL}/preferencias?t=${sub.unsubscribe_token}`;
    const html = buildHtml(preferencesUrl);

    try {
      const r = await fetch('https://api.resend.com/emails', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          'authorization': `Bearer ${RESEND_API_KEY}`,
        },
        body: JSON.stringify({ from: RESEND_FROM, to: sub.email, subject, html }),
      });

      if (r.ok) {
        sent++;
      } else {
        const err = await r.text().catch(() => '');
        failed.push({ email: sub.email, error: err });
      }
    } catch (e) {
      failed.push({ email: sub.email, error: e.message });
    }
  }

  return { ok: true, sent, failed: failed.length, total: subscribers.length, edition };
};
